azure-compliance.control.apimanagement_s.control_definition:
control "apimanagement_service_with_virtual_network" {
  title       = "API Management services should use a virtual network"
  description = "Azure Virtual Network deployment provides enhanced security, isolation and allows you to place your API Management service in a non-internet routable network that you control access to. These networks can then be connected to your on-premises networks using various VPN technologies, which enables access to your backend services within the network and/or on-premises. The developer portal and API gateway, can be configured to be accessible either from the Internet or only within the virtual network."
  query       = query.apimanagement_service_with_virtual_network

  tags = merge(local.regulatory_compliance_apimanagement_common_tags, {
    fedramp_high          = "true"
    nist_sp_800_171_rev_2 = "true"
    nist_sp_800_53_rev_5  = "true"
  })
}

query_definitions.source:
query "apimanagement_service_with_virtual_network" {
  sql = <<-EOQ
    select
      a.id as resource,
      case
        when virtual_network_type != 'None' then 'ok'
        else 'alarm'
      end as status,
      a.name || ' Virtual network is set to '  ||  virtual_network_type as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_api_management a
      left join azure_subscription sub on a.subscription_id = sub.subscription_id;
  EOQ
}

azure-compliance.control.app_configurati.control_definition:
control "app_configuration_encryption_enabled" {
  title       = "App Configuration encryption should be enabled"
  description = "Enabling App Configuration encryption helps protect and safeguard your data to meet your organizational security and compliance commitments."
  query       = query.app_configuration_encryption_enabled

  tags = local.regulatory_compliance_appconfiguration_common_tags
}

query_definitions.source:
query "app_configuration_encryption_enabled" {
  sql = <<-EOQ
    select
      a.id as resource,
      case
        when encryption -> 'keyVaultProperties' ->> 'keyIdentifier' is not null then 'ok'
        else 'alarm'
      end as status,
      case
        when encryption -> 'keyVaultProperties' ->> 'keyIdentifier' is not null then a.name ||  'encryption enabled.'
        else a.name || ' encryption disabled.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_app_configuration a
      left join azure_subscription sub on a.subscription_id = sub.subscription_id;
  EOQ
}

azure-compliance.control.app_configurati.control_definition:
control "app_configuration_private_link_used" {
  title       = "App Configuration should use private link"
  description = "Azure Private Link lets you connect your virtual network to Azure services without a public IP address at the source or destination. The private link platform handles the connectivity between the consumer and services over the Azure backbone network. By mapping private endpoints to your app configuration instances instead of the entire service, you'll also be protected against data leakage risks."
  query       = query.app_configuration_private_link_used

  tags = merge(local.regulatory_compliance_appconfiguration_common_tags, {
    fedramp_high          = "true"
    nist_sp_800_171_rev_2 = "true"
    nist_sp_800_53_rev_5  = "true"
  })
}

control "app_configuration_sku_standard" {
  title       = "App Configuration should use standard SKU"
  description = "Ensure that App Configuration uses standard SKU tier. This control is non-compliant if App Configuration does not use standard SKU."
  query       = query.app_configuration_sku_standard

  tags = local.regulatory_compliance_appconfiguration_common_tags
}

query_definitions.source:
query "app_configuration_sku_standard" {
  sql = <<-EOQ
    select
      a.id as resource,
      case
        when sku_name = 'standard' then 'ok'
        else 'alarm'
      end as status,
        a.name || ' has ' || sku_name || ' SKU tier.' as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_app_configuration a
      left join azure_subscription sub on a.subscription_id = sub.subscription_id;
  EOQ
}

azure-compliance.control.data_factory_en.control_definition:
control "data_factory_encrypted_with_cmk" {
  title       = "Azure data factories should be encrypted with a customer-managed key"
  description = "Use customer-managed keys to manage the encryption at rest of your Azure Data Factory. By default, customer data is encrypted with service-managed keys, but customer-managed keys are commonly required to meet regulatory compliance standards. Customer-managed keys enable the data to be encrypted with an Azure Key Vault key created and owned by you. You have full control and responsibility for the key lifecycle, including rotation and management."
  query       = query.data_factory_encrypted_with_cmk

  tags = merge(local.regulatory_compliance_datafactory_common_tags, {
    nist_sp_800_171_rev_2 = "true"
    nist_sp_800_53_rev_5  = "true"
  })
}

query_definitions.source:
query "data_factory_encrypted_with_cmk" {
  sql = <<-EOQ
    select
      a.id as resource,
      case
        when encryption ->> 'vaultBaseUrl' is not null then 'ok'
        else 'alarm'
      end as status,
      case
        when encryption ->> 'vaultBaseUrl' is not null then a.name || ' encrypted with CMK.'
        else a.name || ' not encrypted with CMK.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_data_factory as a
      left join azure_subscription as sub on sub.subscription_id = a.subscription_id;
  EOQ
}

