azure-compliance.control.cis_v130_8_1.control_definition:
control "cis_v130_8_1" {
  title         = "8.1 Ensure that the expiration date is set on all keys"
  description   = "Ensure that all keys in Azure Key Vault have an expiration time set."
  query         = query.keyvault_key_expiration_set
  documentation = file("./cis_v130/docs/cis_v130_8_1.md")

  tags = merge(local.cis_v130_8_common_tags, {
    cis_item_id = "8.1"
    cis_level   = "1"
    cis_type    = "automated"
    service     = "Azure/KeyVault"
  })
}

query_definitions.source:
query "keyvault_key_expiration_set" {
  sql = <<-EOQ
    select
      kvk.id as resource,
      case
        when enabled and expires_at is null then 'alarm'
        else 'ok'
      end as status,
      vault_name || ' key ' || name ||
      case
        when enabled and expires_at is null then ' expiration date not set.'
        when not enabled then ' disabled.'
        else ' expiration date set to ' || to_char(expires_at, 'DD-Mon-YYYY') || '.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "kvk.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "kvk.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_key_vault_key kvk
      left join azure_subscription as sub on sub.subscription_id = kvk.subscription_id;
  EOQ
}

