control "cis_v130_4_1_3" {
  title         = "4.1.3 Ensure that 'Auditing' Retention is 'greater than 90 days'"
  description   = "SQL Server Audit Retention should be configured to be greater than 90 days."
  query         = query.sql_server_auditing_retention_period_90
  documentation = file("./cis_v130/docs/cis_v130_4_1_3.md")

  tags = merge(local.cis_v130_4_1_common_tags, {
    cis_item_id = "4.1.3"
    cis_level   = "1"
    cis_type    = "automated"
    service     = "Azure/SQL"
  })
}

query_definitions.source:
query "sql_server_auditing_retention_period_90" {
  sql = <<-EOQ
    select
      s.id as resource,
      case
        when (audit -> 'properties' ->> 'retentionDays')::integer = 0 then 'ok'
        when (audit -> 'properties' ->> 'retentionDays')::integer >= 90 then 'ok'
        else 'alarm'
      end as status,
      case
        when (audit -> 'properties' ->> 'retentionDays')::integer = 0 then name || ' audit retention set to unlimited days.'
        when (audit -> 'properties' ->> 'retentionDays')::integer >= 90 then name || ' audit retention greater than 90 days.'
        else  name || ' audit retention less than 90 days.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "s.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "s.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_sql_server s
      cross join lateral jsonb_array_elements(server_audit_policy) audit
      left join azure_subscription sub on sub.subscription_id = s.subscription_id;
  EOQ
}

