// Enable TDE on an existing Azure SQL Database
resource tde 'Microsoft.Sql/servers/databases/transparentDataEncryption@2021-11-01' = {
  name: '<example_server_name>/<example_database_name>/current'
  properties: {
    state: 'Enabled' // critical: enables Transparent Data Encryption (TDE)
  }
}
