def _absent_default(item, path, default):
    # Only called after full GET validation. Explicit coverage errors still raise.
    node = item
    parts = path.split('.')
    for part in parts:
        if part not in node and part not in node.get('_coverage', {}):
            return default
        node = get(node, part)
    return node

