        parts = re.split('/providers/', value['id'], flags=re.I)[-1].split('/')
        result['type'] = '/'.join([parts[0], *parts[1::2]])
        result.setdefault('_provenance', {})['type_source'] = 'native_resource_path'
    kind = str(result.get('type', '')).casefold().rsplit('/', 1)[-1]
